#!/usr/bin/env python3
"""Serial Step13 native comparison runner.

This is deliberately inert unless ``--run`` is supplied.  The Rust test and
its fresh guest protocol remain authoritative; this driver only selects the
explicit corpus filter, retains receipts, and rejects incomplete results.
"""

from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import math
import os
from pathlib import Path
import re
import shlex
import subprocess
import time


ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).resolve().parent
CONFIG = Path("/tmp/opforge-performance.fs-uae")
FS_UAE = "/Applications/FS-UAE.app/Contents/MacOS/fs-uae"
CORPUS_FILTER = "external_fs_uae_native_production_corpus_parity"
BASE_TEST = ["cargo", "test", "--locked", "-p", "asm"]
NATIVE_FNV = re.compile(r"^fnv1a64:[0-9a-f]{16}$")


def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_manifest() -> dict:
    source = ROOT / "scripts/performance/production_corpus.py"
    spec = importlib.util.spec_from_file_location("production_corpus", source)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot load corpus helper: {source}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.manifest()


def config_identity() -> dict:
    data = CONFIG.read_bytes()
    text = data.decode("utf-8")
    required = ("cpu = 68020", "uae_cpu_speed = max", "jit_compiler = 0")
    missing = [line for line in required if line not in text]
    if missing:
        raise RuntimeError(f"FS-UAE config is not pinned to 68020/max/JIT0: {missing}")
    return {"path": str(CONFIG), "bytes": len(data), "sha256": hashlib.sha256(data).hexdigest()}


def corpus_env(case_id: str, mode: str) -> dict[str, str]:
    return {
        "OPFORGE_PERFORMANCE_CORPUS": "1",
        "OPFORGE_NATIVE_CORPUS_CASES": case_id,
        "OPFORGE_NATIVE_CORPUS_CLEAR": "longword",
        "OPFORGE_NATIVE_CORPUS_STATEMENT_CLEAR": mode,
        "OPFORGE_NATIVE_CORPUS_PROFILE": "off",
        "OPFORGE_FS_UAE_SMOKE": "1",
        "OPFORGE_FS_UAE_BIN": FS_UAE,
        "OPFORGE_FS_UAE_CONFIG_TEMPLATE": str(CONFIG),
        "OPFORGE_FS_UAE_ARGS": "{fsuae_config}",
        "OPFORGE_FS_UAE_POST_START_TIMEOUT_MS": "120000",
        "OPFORGE_FS_UAE_POLL_MS": "250",
        "RUST_TEST_THREADS": "1",
    }


def level_d_env() -> dict[str, str]:
    return {
        "OPFORGE_FS_UAE_SMOKE": "1",
        "OPFORGE_FS_UAE_BIN": FS_UAE,
        "OPFORGE_FS_UAE_CONFIG_TEMPLATE": str(CONFIG),
        "OPFORGE_FS_UAE_ARGS": "{fsuae_config}",
        "OPFORGE_FS_UAE_POST_START_TIMEOUT_MS": "120000",
        "OPFORGE_FS_UAE_POLL_MS": "250",
        "RUST_TEST_THREADS": "1",
    }


def command_for(test_filter: str) -> list[str]:
    return [*BASE_TEST, test_filter, "--", "--nocapture", "--test-threads=1"]


def strict_result(row: object, case: dict, case_id: str, mode: str,
                  package_sha256: str) -> tuple[bool, str]:
    if not isinstance(row, dict):
        return False, "missing or non-object CORPUS_RESULT"
    if row.get("id") != case_id:
        return False, "CORPUS_RESULT case id mismatch"
    if row.get("case_sha256") != case["sha256"]:
        return False, "CORPUS_RESULT source/case hash mismatch"
    if row.get("package_sha256") != package_sha256:
        return False, "CORPUS_RESULT package hash mismatch"
    if row.get("statement_clear_mode") != mode:
        return False, "CORPUS_RESULT statement-clear mode mismatch"
    if row.get("clear_mode") != "longword" or row.get("profile_mode") != "off":
        return False, "CORPUS_RESULT clear/profile mode mismatch"
    if row.get("complete") is not True or type(row.get("exit_status")) is not int or row["exit_status"] != 0:
        return False, "guest protocol is incomplete or guest exit is nonzero"
    if type(row.get("timing_poll_interval_ms")) is not int or row["timing_poll_interval_ms"] != 250:
        return False, "timing poll interval is not the required 250 ms"
    timing = row.get("start_to_done_host_seconds")
    if type(timing) not in (int, float) or not math.isfinite(timing) or timing <= 0:
        return False, "completed guest has no valid START-to-DONE duration"
    digest = row.get("native_image_digest")
    if not isinstance(digest, str) or not NATIVE_FNV.fullmatch(digest):
        return False, "native FNV image identity is missing or malformed"
    if not isinstance(row.get("exact_artifacts"), list) or not row["exact_artifacts"]:
        return False, "exact artifact paths are missing"
    return True, "passed"


def run_process(label: str, command: list[str], additions: dict[str, str], common: dict,
                *, case: dict | None = None, case_id: str | None = None,
                mode: str | None = None, sequence: int) -> dict:
    env = os.environ.copy()
    env.update(additions)
    started = time.perf_counter_ns()
    timeout = False
    try:
        completed = subprocess.run(command, cwd=ROOT, env=env, capture_output=True,
                                   text=True)
        stdout, stderr, returncode = completed.stdout, completed.stderr, completed.returncode
    except subprocess.TimeoutExpired as error:
        timeout = True
        stdout = error.stdout.decode(errors="replace") if isinstance(error.stdout, bytes) else (error.stdout or "")
        stderr = error.stderr.decode(errors="replace") if isinstance(error.stderr, bytes) else (error.stderr or "")
        returncode = None
    wall_seconds = (time.perf_counter_ns() - started) / 1_000_000_000
    transcript = (f"$ {shlex.join(command)}\n"
                  f"environment: {json.dumps(additions, sort_keys=True)}\n\n"
                  f"--- stdout ---\n{stdout}\n--- stderr ---\n{stderr}")
    stem = f"{sequence:03d}-{label}"
    (OUT / f"{stem}.log").write_text(transcript, encoding="utf-8")
    rows = []
    for line in f"{stdout}\n{stderr}".splitlines():
        if line.startswith("CORPUS_RESULT "):
            try:
                rows.append(json.loads(line[len("CORPUS_RESULT "):]))
            except json.JSONDecodeError:
                rows.append(None)
    if "exceeded the post-start timeout" in transcript.lower():
        passed, reason = False, "guest timeout (post-start protocol)"
    elif case is not None and not timeout and returncode == 0 and len(rows) == 1:
        passed, reason = strict_result(rows[0], case, case_id or "", mode or "", common["package_sha256"])
    elif timeout:
        passed, reason = False, "process timeout (not reclassified as correctness)"
    elif case is not None:
        passed, reason = False, f"process={returncode}; expected exactly one valid CORPUS_RESULT"
    else:
        skipped = "SKIP:" in transcript or "skipped" in transcript.lower()
        summaries = re.findall(r"test result: (?:ok|FAILED)\. (\d+) passed; (\d+) failed;", transcript)
        exactly_one_pass = len(summaries) == 1 and summaries[0] == ("1", "0")
        passed = returncode == 0 and exactly_one_pass and not skipped
        reason = "passed" if passed else "Level D did not prove exactly one passed test and zero failed tests"
    result = {
        "sequence": sequence, "label": label, "command": command,
        "command_text": shlex.join(command), "environment": additions,
        "process_returncode": returncode, "wall_seconds": wall_seconds,
        "timeout": timeout, "passed": passed, "reason": reason,
        "raw_log": str(OUT / f"{stem}.log"),
    }
    if case is not None:
        row = rows[0] if len(rows) == 1 else None
        result.update({
            "case_id": case_id, "statement_clear_mode": mode,
            "case_sha256": case["sha256"], "source_hashes": {
                name: info["sha256"] for name, info in case["files"].items()
            },
            "expected_artifacts": case.get("expected_artifacts", {}),
            "corpus_sha256": common["corpus_sha256"],
            "package_sha256": common["package_sha256"],
            "native_source_sha256": common["native_source_sha256"],
            "config": common["config"],
            "native_image_digest": row.get("native_image_digest") if isinstance(row, dict) else None,
            "native_fnv": row.get("native_image_digest") if isinstance(row, dict) else None,
            "start_to_done_host_seconds": row.get("start_to_done_host_seconds") if isinstance(row, dict) else None,
            "corpus_result": row,
        })
    (OUT / f"{stem}.json").write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return result


def validate_comparison(receipts: list[dict]) -> dict:
    """Validate identity stability separately from native parity correctness."""
    failures = []
    for case_id in ("B01", "B03"):
        mode_digests = {}
        for mode in ("full", "live"):
            rows = [receipt for receipt in receipts
                    if receipt.get("case_id") == case_id
                    and receipt.get("statement_clear_mode") == mode
                    and receipt.get("passed")]
            qualified = [receipt for receipt in rows if receipt.get("qualified")]
            digests = {receipt.get("native_fnv") for receipt in rows}
            mode_digests[mode] = sorted(digests)
            if not qualified:
                failures.append(f"{case_id}/{mode}: no qualified successful receipt")
            if len(digests) != 1:
                failures.append(f"{case_id}/{mode}: successful receipts have inconsistent FNV identities")
        if set(mode_digests["full"]) & set(mode_digests["live"]):
            failures.append(f"{case_id}: full/live FNV identities are not distinct")
    all_mode_digests = {
        mode: sorted({receipt.get("native_fnv") for receipt in receipts
                      if receipt.get("statement_clear_mode") == mode and receipt.get("passed")})
        for mode in ("full", "live")
    }
    for mode, digests in all_mode_digests.items():
        if len(digests) != 1:
            failures.append(f"{mode}: image identity differs across successful corpus cases")
    if set(all_mode_digests["full"]) & set(all_mode_digests["live"]):
        failures.append("full/live images must differ across the complete corpus comparison")
    return {"passed": not failures, "failures": failures, "mode_digests": all_mode_digests}


def run() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    config = config_identity()
    marker = OUT / "RUN_STARTED"
    try:
        descriptor = os.open(marker, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
    except FileExistsError as error:
        raise RuntimeError(f"refusing to overwrite an existing run: {marker}") from error
    with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
        stream.write(json.dumps({"started_unix": time.time(), "config": config}, sort_keys=True) + "\n")
    manifest = load_manifest()
    cases = {case["id"]: case for case in manifest["cases"]}
    selected = {case_id: cases[case_id] for case_id in ("B01", "B03", "B10")}
    common = {"corpus_sha256": manifest["sha256"], "package_sha256": manifest["package"]["sha256"], "config": config,
              "native_source_sha256": sha256(ROOT / "native/motorola68000/amigaos/opasm/opasm_engine.asm")}
    (OUT / "manifest.json").write_text(json.dumps({"manifest": manifest, "identity": common}, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    sequence = 0
    receipts = []
    timing_failure_seen = False
    for case_id in ("B01", "B03"):
        for pair in range(1, 4):
            pair_receipts = []
            modes = ("full", "live") if pair % 2 else ("live", "full")
            for mode in modes:
                sequence += 1
                receipt = run_process(f"{case_id}-{mode}-pair{pair}", command_for(CORPUS_FILTER), corpus_env(case_id, mode), common,
                                      case=selected[case_id], case_id=case_id, mode=mode, sequence=sequence)
                receipt["qualified"] = not timing_failure_seen
                receipts.append(receipt)
                pair_receipts.append(receipt)
            if any(not receipt["passed"] for receipt in pair_receipts):
                for receipt in pair_receipts:
                    receipt["qualified"] = False
                timing_failure_seen = True
    # B10 is a fixed-budget later case: attempt both modes even after a prior failure,
    # and never repeat either invocation.
    for mode in ("full", "live"):
        sequence += 1
        receipts.append(run_process(f"B10-{mode}-fixed", command_for(CORPUS_FILTER), corpus_env("B10", mode), common,
                                    case=selected["B10"], case_id="B10", mode=mode, sequence=sequence))
    for label, test_filter in (
        ("early-error", "external_fs_uae_session_clear_early_error_preserves_diagnostic"),
        ("capacity-over512", "native_statement_capacity_over_512_fs_uae"),
    ):
        sequence += 1
        receipts.append(run_process(label, command_for(test_filter), level_d_env(), common, sequence=sequence))
    comparison = validate_comparison(receipts)
    (OUT / "summary.json").write_text(json.dumps({"receipts": receipts,
                                                    "timing_failure_seen": timing_failure_seen,
                                                    "comparison_validation": comparison}, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return 0 if all(receipt["passed"] for receipt in receipts) and comparison["passed"] else 1


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run", action="store_true", help="run FS-UAE/Cargo measurements after review")
    args = parser.parse_args()
    if not args.run:
        print("Refusing to start native measurements; pass --run after explicit review/GO.")
        return 2
    return run()


if __name__ == "__main__":
    raise SystemExit(main())

